#!/usr/bin/env bash
# Print the three most frequent client IPs, retaining log order for ties.
set -euo pipefail

script_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)

awk '
{
    ip = $1
    if (!(ip in count))
        first_seen[ip] = NR
    count[ip]++
}
END {
    for (ip in count)
        print count[ip], first_seen[ip], ip
}
' "$script_dir/access.log" |
    sort -k1,1nr -k2,2n |
    head -n 3 |
    awk '{ print $3 }'
